package com.nigson.acceptance.carrier;
import java.util.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.order.OrderAuthority;
import com.nigson.commerce.pricing.PricingAuthority;
import com.nigson.shared.security.ActorAssertion;
import static org.assertj.core.api.Assertions.*;
class ShipmentTrackingPersistenceTest {
 ShipmentFixture f;ShipmentTrackingService service;ActorAssertion.Actor customer;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"carrier-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);f=new ShipmentFixture(jdbc,manager);customer=new ActorAssertion.Actor(f.inventory.orders.party,"https://identity.synthetic.invalid/realms/test",f.inventory.orders.party.toString(),null,Set.of("CUSTOMER"),Set.of(),null);service=new ShipmentTrackingService(jdbc,f.repository,new OrderAuthority(jdbc,new PricingAuthority(jdbc,Clock.systemUTC(),3,"SYNTHETIC_DISTRIBUTOR_BUY"),Clock.systemUTC()),manager);}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 @Test void onlyOwnedCurrentCustomerCanReadAndPrivateNotesNeverLeave(){var shipment=f.create("5","FEDEX",null,"tracking");f.inventory.jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at,note) VALUES (?,'test',?,'FEDEX',?,'UNKNOWN',now(),'Synthetic private internal provider diagnostic')",UUID.randomUUID(),shipment.id(),UUID.randomUUID().toString());var result=service.tracking(customer,f.order);assertThat(result.shipments()).hasSize(1);assertThat(result.shipments().getFirst().status()).isEqualTo("CREATED");assertThat(result.events()).allSatisfy(event->assertThat(event.note()).isNull());var other=new ActorAssertion.Actor(f.inventory.actor.party(),f.inventory.actor.identityIssuer(),f.inventory.actor.identitySubject(),null,Set.of("CUSTOMER"),Set.of(),null);assertThatThrownBy(()->service.tracking(other,f.order)).hasMessage("NOT_FOUND");f.inventory.jdbc.update("UPDATE commerce.party SET status='SUSPENDED' WHERE id=?",customer.party());assertThatThrownBy(()->service.tracking(customer,f.order)).hasMessage("ACCESS_DENIED");}
 @Test void latestHundredEventsHaveStableOrderAndRetainAllDurableHistory(){var shipment=f.create("5","FEDEX",null,"tracking");Instant base=Instant.now().minusSeconds(300);for(int n=0;n<120;n++)f.inventory.jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,'test',?,'FEDEX',?,'UNKNOWN',?)",UUID.randomUUID(),shipment.id(),UUID.randomUUID().toString(),java.sql.Timestamp.from(base.plusSeconds(n)));var first=service.tracking(customer,f.order);assertThat(first.events()).hasSize(100);assertThat(service.tracking(customer,f.order)).isEqualTo(first);assertThat(first.events()).isSortedAccordingTo(java.util.Comparator.comparing(ShipmentTrackingService.Event::occurredAt).reversed());assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.shipment_event WHERE shipment_id=?",Integer.class,shipment.id())).isEqualTo(121);assertThat(f.value("allocated")).isEqualByComparingTo("5");}
 @Test void unshippedOrderReturnsEmptyOwnedProjection(){var result=service.tracking(customer,f.order);assertThat(result.shipments()).isEmpty();assertThat(result.events()).isEmpty();}
 @Test void historicalOrganizationReadNeedsCurrentMembershipButNoBuyingEntitlement(){UUID org=UUID.randomUUID();var jdbc=f.inventory.jdbc;jdbc.update("INSERT INTO commerce.organization(id,created_by,updated_by,name,country_code,status) VALUES (?,'test','test','Synthetic historical organization','NG','ACTIVE')",org);jdbc.update("INSERT INTO commerce.organization_membership(id,created_by,updated_by,organization_id,party_id,role,status) VALUES (?,'test','test',?,?,'BUYER','ACTIVE')",UUID.randomUUID(),org,customer.party());jdbc.update("UPDATE commerce.sales_order SET organization_id=? WHERE id=?",org,f.order);try{assertThat(service.tracking(customer,f.order).orderId()).isEqualTo(f.order);jdbc.update("UPDATE commerce.organization_membership SET status='SUSPENDED' WHERE organization_id=?",org);assertThatThrownBy(()->service.tracking(customer,f.order)).hasMessage("NOT_FOUND");}finally{jdbc.update("UPDATE commerce.sales_order SET organization_id=NULL WHERE id=?",f.order);jdbc.update("DELETE FROM commerce.organization_membership WHERE organization_id=?",org);jdbc.update("DELETE FROM commerce.organization WHERE id=?",org);}}

}
